module signal_generator(
    input clk, input rst_n,
    output reg [4:0] wave
);
    reg state;
    reg next_state;
    reg [4:0] next_wave;
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            state <= 1'b0;
            wave <= 5'b0;
        end else begin
            state <= next_state;
            wave <= next_wave;
        end
    end
    always @(*) begin
        next_state = state;
        next_wave = wave;
        if (state == 1'b0) begin
            if (wave != 5'd31) begin
                next_wave = wave + 1;
            end else begin
                next_state = 1'b1;
            end
        end else begin
            if (wave != 5'd0) begin
                next_wave = wave - 1;
            end else begin
                next_state = 1'b0;
            end
        end
    end
endmodule
